# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs, floor_=6):
    return [v for v in xs if v > floor_]

# region: sift
def sift(xs, offset=-1):
    return [v + offset for v in xs]

# region: render
def render(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(render(sift(digest(intake(shape(raw))))))

